from collections import deque

def solution(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]   # strings are immutable, so mark visits here
    count = 0
    for r0 in range(rows):
        for c0 in range(cols):
            if grid[r0][c0] != '1' or seen[r0][c0]:
                continue
            count += 1                       # a new cluster starts here
            seen[r0][c0] = True              # mark when you enqueue, not when you pop
            queue = deque([(r0, c0)])
            while queue:
                r, c = queue.popleft()
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1' and not seen[nr][nc]:
                        seen[nr][nc] = True
                        queue.append((nr, nc))
    return count

