def island_of(grid, r0, c0):
    # Flood fill from scratch and return every cell of this island.
    rows, cols = len(grid), len(grid[0])
    found = {(r0, c0)}
    stack = [(r0, c0)]
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1' and (nr, nc) not in found:
                found.add((nr, nc))
                stack.append((nr, nc))
    return found

def solution(grid):
    # Count land cells that are the first cell (row-major) of their island.
    # Re-floods the whole island for every land cell: O((rows * cols)^2) worst case.
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == '1' and min(island_of(grid, r, c)) == (r, c):
                count += 1
    return count
